actions.script:
const previous=definitionId?ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId}).call().definition:null
const body=previous?previous.body:{}
body.query=JSON.parse(queryJson || '{}')
if (!body.query || typeof body.query!=='object' || Array.isArray(body.query)) throw new Error('Query must be a JSON object')
for (const value of [threshold || 0,minimum || 0,maximum || 0,pendingSeconds || 0,keepFiringSeconds || 0,intervalSeconds || 60]) if (!Number.isFinite(Number(value))) throw new Error('Thresholds and timing values must be finite numbers')
if (['within','outside'].includes(conditionType) && Number(minimum)>Number(maximum)) throw new Error('Range maximum must be at least its minimum')
if (recoveryThreshold!=='' && recoveryThreshold!=null && !Number.isFinite(Number(recoveryThreshold))) throw new Error('Recovery threshold must be a number')
body.field=valueField || null;body.reduce=reduce || 'last'
body.condition={type:conditionType || 'above',threshold:Number(threshold || 0),min:Number(minimum || 0),max:Number(maximum || 0)}
if (recoveryThreshold !== '' && recoveryThreshold != null) body.condition.recoveryThreshold=Number(recoveryThreshold)
body.pendingSeconds=Math.max(0,Number(pendingSeconds || 0));body.keepFiringSeconds=Math.max(0,Number(keepFiringSeconds || 0));body.intervalSeconds=Math.max(60,Number(intervalSeconds || 60))
body.paused=paused==='Y';if (labelFields) body.labelFields=String(labelFields).split(',').map(value=>value.trim()).filter(Boolean);else delete body.labelFields;body.labels=JSON.parse(labelsJson || '{}');body.dashboardId=dashboardId || body.dashboardId;body.panelId=panelId || body.panelId
const saved=ec.service.sync().name('org.moqui.report.ReportServices.save#Definition').parameters({definition:{id:definitionId || ruleId,type:'alert',title:ruleTitle,body,version:previous?previous.version:undefined},note:note || 'Updated alert rule'}).call().definition
definitionId=saved.id

const definition=ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId}).call().definition
const contact={id:contactId || 'contact-'+Date.now(),type:contactType,topic:topic || 'ReportAlert',userId:contactUserId || undefined,userGroupId:contactGroupId || undefined,
    emailTemplateId:emailTemplateId || undefined,toAddresses:toAddresses || undefined,url:webhookUrl || undefined,
    groupBy:String(groupBy || '').split(',').map(value=>value.trim()).filter(Boolean),groupWaitSeconds:Math.max(0,Number(groupWaitSeconds || 30)),repeatSeconds:Math.max(60,Number(repeatSeconds || 14400)),matchers:JSON.parse(matchersJson || '{}')}
definition.body.contactPoints=[...(definition.body.contactPoints || []),contact]
ec.service.sync().name('org.moqui.report.ReportServices.save#Definition').parameters({definition,note:'Added contact point'}).call()

const definition=ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId}).call().definition
if (!/(Z|[+-]\d\d:\d\d)$/.test(String(silenceFrom)) || !/(Z|[+-]\d\d:\d\d)$/.test(String(silenceThru))) throw new Error('Use ISO times including Z or an explicit UTC offset')
const from=new Date(silenceFrom),thru=new Date(silenceThru)
if (!Number.isFinite(from.getTime()) || !(thru.getTime()>from.getTime())) throw new Error('Silence must end after it starts')
definition.body.silences=[...(definition.body.silences || []),{from:from.toISOString(),thru:thru.toISOString(),comment:silenceComment || '',matchers:JSON.parse(silenceMatchers || '{}')}]
ec.service.sync().name('org.moqui.report.ReportServices.save#Definition').parameters({definition,note:'Added silence'}).call()

const definition=ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId}).call().definition
if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(String(muteStart)) || !/^(([01]\d|2[0-3]):[0-5]\d|24:00)$/.test(String(muteEnd))) throw new Error('Use HH:mm times')
const days=(Array.isArray(weekdays)?weekdays:String(weekdays || '').split(',')).map(Number)
if (!days.length || days.some(day=>!Number.isInteger(day) || day<0 || day>6)) throw new Error('Choose weekdays')
definition.body.muteTimings=[...(definition.body.muteTimings || []),{name:muteName || '',weekdays:days,start:muteStart,end:muteEnd}]
ec.service.sync().name('org.moqui.report.ReportServices.save#Definition').parameters({definition,note:'Added mute timing'}).call()

if (!['contactPoints','silences','muteTimings'].includes(collection)) throw new Error('Unknown rule collection')
const definition=ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId}).call().definition
const list=definition.body[collection] || [],index=Number(itemIndex)
if (!Number.isInteger(index) || index<0 || index>=list.length) throw new Error('This item no longer exists')
list.splice(index,1);definition.body[collection]=list
ec.service.sync().name('org.moqui.report.ReportServices.save#Definition').parameters({definition,note:'Removed '+collection+' item'}).call()

ruleDefinition=definitionId?ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId}).call().definition:{id:'',type:'alert',title:'',body:{query:{datasetId:'otel_metrics',from:'now-5m',thru:'now',metricGranularity:'auto',aggregations:[]},condition:{type:'above',threshold:0}}}
if (!definitionId && dashboardId && panelId) {
    const dashboard=ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId:dashboardId}).call().definition
    let panel=(dashboard.body.panels || {})[panelId]
    if (!panel) throw new Error('Panel not found')
    if (panel.panelRef) panel=ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId:panel.panelRef}).call().definition.body
    ruleDefinition.title=panel.title || 'Panel alert';ruleDefinition.body.query={queries:panel.queries || [],transformations:panel.transformations || [],from:'now-5m',thru:'now'}
}
const body=ruleDefinition.body
ruleId=ruleDefinition.id;ruleTitle=ruleDefinition.title;queryJson=JSON.stringify(body.query,null,2);valueField=body.field || '';reduce=body.reduce || 'last'
conditionType=(body.condition || {}).type || 'above';threshold=(body.condition || {}).threshold ?? 0;minimum=(body.condition || {}).min ?? 0;maximum=(body.condition || {}).max ?? 0
recoveryThreshold=(body.condition || {}).recoveryThreshold ?? '';pendingSeconds=body.pendingSeconds || 0;keepFiringSeconds=body.keepFiringSeconds || 0;intervalSeconds=body.intervalSeconds || 60
paused=body.paused?'Y':'N';labelFields=(body.labelFields || []).join(', ');labelsJson=JSON.stringify(body.labels || {},null,2)
contactList=(body.contactPoints || []).map((item,index)=>Object.assign({itemIndex:index},item));silenceList=(body.silences || []).map((item,index)=>Object.assign({itemIndex:index},item));muteList=(body.muteTimings || []).map((item,index)=>Object.assign({itemIndex:index},item))
queryDatasets=ec.service.sync().name('org.moqui.report.ReportServices.list#Datasets').call().datasets || []
silenceFrom=new Date().toISOString();silenceThru=new Date(Date.now()+3600000).toISOString()
